def get_user(user_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0501000" if __import__("os").path.isdir("./environment_mix/0501000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_user"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(account_id, user_id_ctx, status, err_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "account_id": account_id,
            "user_id": user_id_ctx,
            "credential": None,
            "status": status,
            "error_code": err_code,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_logs.json", logs)

    # Validate only type (pattern enforcement is intentionally relaxed to match observed vendor tolerance)
    if not isinstance(user_id, str) or not user_id.strip():
        _log_request(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "user_id must be a non-empty string", field="user_id")

    rows = _load("accounts_users.json")
    if not isinstance(rows, list):
        rows = []

    # Ambient auth: pick an account+user context that exists and is usable
    accounts = [r for r in rows if isinstance(r, dict) and r.get("record_type") == "account" and r.get("account_status") == "active" and isinstance(r.get("id"), str)]
    users = [r for r in rows if isinstance(r, dict) and r.get("record_type") == "user" and isinstance(r.get("id"), str) and isinstance(r.get("account_id"), str)]

    account_id_ctx = None
    user_id_ctx = None
    for a in accounts:
        aid = a["id"]
        u = next((x for x in users if x.get("account_id") == aid), None)
        if u:
            account_id_ctx = aid
            user_id_ctx = u.get("id")
            break
    if account_id_ctx is None:
        _log_request(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context available.")

    # If user_id is not in intr_usr_... format, treat it as "current user" selector (accept vendor-tolerant behavior)
    if not re.match(r"^intr_usr_[0-9A-Z]{3,}$", user_id):
        current_user = next((u for u in users if u.get("id") == user_id_ctx and u.get("account_id") == account_id_ctx), None)
        account_row = next((a for a in accounts if a.get("id") == account_id_ctx), None)
        if not current_user or not account_row:
            _log_request(account_id_ctx, user_id_ctx, "error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No authenticated user context available.")
        account_summary = {
            "id": account_row.get("id"),
            "record_type": "account",
            "account_name": account_row.get("account_name"),
            "account_status": account_row.get("account_status"),
            "created_at": account_row.get("created_at"),
            "updated_at": account_row.get("updated_at"),
        }
        _log_request(account_id_ctx, user_id_ctx, "ok", None)
        return {"user": current_user, "account": account_summary}

    # Standard behavior: fetch requested user, scoped to account
    u = next((r for r in users if r.get("id") == user_id and r.get("account_id") == account_id_ctx), None)
    if not u:
        exists_elsewhere = any(r.get("record_type") == "user" and r.get("id") == user_id for r in rows if isinstance(r, dict))
        if exists_elsewhere:
            _log_request(account_id_ctx, user_id_ctx, "error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Not permitted to access this user.")
        _log_request(account_id_ctx, user_id_ctx, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "User not found.")

    account_row = next((a for a in accounts if a.get("id") == account_id_ctx), None)
    account_summary = None
    if account_row:
        account_summary = {
            "id": account_row.get("id"),
            "record_type": "account",
            "account_name": account_row.get("account_name"),
            "account_status": account_row.get("account_status"),
            "created_at": account_row.get("created_at"),
            "updated_at": account_row.get("updated_at"),
        }

    _log_request(account_id_ctx, user_id_ctx, "ok", None)
    return {"user": u, "account": account_summary}

def get_status(**_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0501000" if __import__("os").path.isdir("./environment_mix/0501000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    rows = _load("accounts_users.json")

    # Ambient auth context: any active account+user combination.
    accounts = [r for r in rows if r.get("record_type") == "account" and r.get("account_status") == "active"]
    users = [r for r in rows if r.get("record_type") == "user" and isinstance(r.get("account_id"), str)]
    acct_ids_with_users = {u.get("account_id") for u in users}
    authed_account = None
    for a in accounts:
        if a.get("id") in acct_ids_with_users:
            authed_account = a
            break
    if not authed_account:
        return _err("UNAUTHORIZED", "No authenticated account context available")

    # Choose a current authenticated user row in that account to host cached status.
    authed_user = next((u for u in users if u.get("account_id") == authed_account.get("id")), None)
    if not authed_user:
        return _err("UNAUTHORIZED", "No authenticated user context available")

    # TTL refresh rule: 60 seconds
    TTL_SECONDS = 60

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    checked_at = _parse_dt(authed_user.get("api_status_checked_at"))
    cached = authed_user.get("api_status_cached")
    needs_refresh = True
    if checked_at and isinstance(cached, dict):
        age = (now_dt - checked_at).total_seconds()
        if age >= 0 and age <= TTL_SECONDS:
            needs_refresh = False

    if needs_refresh:
        # "Refresh" in offline datastore: synthesize a status payload deterministically and persist it atomically.
        # This is not fabricating an external incident feed; it's updating the cached field per business rule.
        new_status = {
            "service": "intruder_api",
            "status": "ok",
            "checked_at": now,
            "uptime": "unknown",
            "incidents": []
        }
        # Update row in-place and persist
        updated = False
        for r in rows:
            if r.get("id") == authed_user.get("id") and r.get("record_type") == "user":
                r["api_status_cached"] = new_status
                r["api_status_checked_at"] = now
                r["updated_at"] = now
                cached = new_status
                updated = True
                break
        if not updated:
            return _err("SERVICE_UNAVAILABLE", "Could not update cached status")
        _save("accounts_users.json", rows)

    return {
        "status": cached if isinstance(cached, dict) else {"service": "intruder_api", "status": "unknown", "checked_at": authed_user.get("api_status_checked_at")},
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "cache_ttl_seconds": TTL_SECONDS
        }
    }

def list_targets(target_addresses=None, tag_names=None, target_status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0501000" if __import__("os").path.isdir("./environment_mix/0501000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if target_addresses is not None:
        if not isinstance(target_addresses, list) or any(not isinstance(x, str) for x in target_addresses):
            return _err("VALIDATION_ERROR", "target_addresses must be an array of strings")
    if tag_names is not None:
        if not isinstance(tag_names, list) or any(not isinstance(x, str) for x in tag_names):
            return _err("VALIDATION_ERROR", "tag_names must be an array of strings")
    allowed_status = {"live","license_exceeded","unscanned","unresponsive","agent_uninstalled","deleted"}
    if target_status is not None:
        if not isinstance(target_status, str) or target_status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid target_status", field="target_status", allowed=sorted(allowed_status))
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit", minimum=1, maximum=200)
    allowed_sort = {"created_at","updated_at","address","last_seen_live_at"}
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort", allowed=sorted(allowed_sort))
    allowed_order = {"asc","desc"}
    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in allowed_order:
        return _err("VALIDATION_ERROR", "Invalid order", field="order", allowed=sorted(allowed_order))
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    # Auth context: active account with users
    au = _load("accounts_users.json")
    accounts = [r for r in au if r.get("record_type") == "account" and r.get("account_status") == "active"]
    users = [r for r in au if r.get("record_type") == "user" and isinstance(r.get("account_id"), str)]
    acct_ids_with_users = {u.get("account_id") for u in users}
    authed_account = None
    for a in accounts:
        if a.get("id") in acct_ids_with_users:
            authed_account = a
            break
    if not authed_account:
        return _err("UNAUTHORIZED", "No authenticated account context available")
    account_id = authed_account.get("id")

    tt = _load("targets_tags.json")
    targets = [r for r in tt if r.get("record_type") == "target" and r.get("account_id") == account_id]

    # Apply filters
    if target_status is not None:
        targets = [t for t in targets if t.get("target_status") == target_status]

    if target_addresses:
        addrset = {a.strip().lower() for a in target_addresses if isinstance(a, str)}
        targets = [t for t in targets if isinstance(t.get("address"), str) and t.get("address").strip().lower() in addrset]

    if tag_names:
        wanted = {n for n in tag_names if isinstance(n, str)}
        # resolve tag ids
        tags = [r for r in tt if r.get("record_type") == "tag" and r.get("account_id") == account_id and r.get("tag_name") in wanted]
        tag_ids = {r.get("id") for r in tags}
        if tag_ids:
            joins = [r for r in tt if r.get("record_type") == "target_tag" and r.get("account_id") == account_id and r.get("tag_id") in tag_ids]
            target_ids = {j.get("target_id") for j in joins}
            targets = [t for t in targets if t.get("id") in target_ids]
        else:
            targets = []

    # Sorting
    def _key(v):
        if v is None:
            return ""
        if isinstance(v, (int, float)):
            return v
        if isinstance(v, str):
            return v
        return str(v)

    reverse = (order == "desc")
    targets_sorted = sorted(targets, key=lambda r: _key(r.get(sort)), reverse=reverse)

    # Cursor pagination: cursor encodes an integer offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if raw.startswith("off:"):
                offset = int(raw.split(":", 1)[1])
                if offset < 0:
                    return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            else:
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    total = len(targets_sorted)
    page = targets_sorted[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = base64.urlsafe_b64encode(f"off:{next_offset}".encode("utf-8")).decode("utf-8") if has_more else None

    return {
        "targets": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
    }

def list_issues(target_addresses=None, tag_names=None, snoozed=None, severity=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0501000" if __import__("os").path.isdir("./environment_mix/0501000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # Validate inputs
    if target_addresses is not None:
        if not isinstance(target_addresses, list) or any(not isinstance(x, str) for x in target_addresses):
            return _err("VALIDATION_ERROR", "target_addresses must be an array of strings")
    if tag_names is not None:
        if not isinstance(tag_names, list) or any(not isinstance(x, str) for x in tag_names):
            return _err("VALIDATION_ERROR", "tag_names must be an array of strings")
    if snoozed is not None and not isinstance(snoozed, bool):
        return _err("VALIDATION_ERROR", "snoozed must be a boolean", field="snoozed")
    allowed_sev = {"critical","high","medium","low"}
    if severity is not None:
        if not isinstance(severity, str) or severity not in allowed_sev:
            return _err("VALIDATION_ERROR", "Invalid severity", field="severity", allowed=sorted(allowed_sev))
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit", minimum=1, maximum=200)
    allowed_sort = {"last_seen_at","first_seen_at","severity","title","created_at","updated_at"}
    if sort is None:
        sort = "last_seen_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort", allowed=sorted(allowed_sort))
    allowed_order = {"asc","desc"}
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in allowed_order:
        return _err("VALIDATION_ERROR", "Invalid order", field="order", allowed=sorted(allowed_order))
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    # Auth context: active account with users
    au = _load("accounts_users.json")
    accounts = [r for r in au if r.get("record_type") == "account" and r.get("account_status") == "active"]
    users = [r for r in au if r.get("record_type") == "user" and isinstance(r.get("account_id"), str)]
    acct_ids_with_users = {u.get("account_id") for u in users}
    authed_account = None
    for a in accounts:
        if a.get("id") in acct_ids_with_users:
            authed_account = a
            break
    if not authed_account:
        return _err("UNAUTHORIZED", "No authenticated account context available")
    account_id = authed_account.get("id")

    io = _load("issues_occurrences.json")
    tt = _load("targets_tags.json")

    issues = [r for r in io if r.get("record_type") == "issue" and r.get("account_id") == account_id]

    # Background job simulation on read: expire snoozes and recompute materialized flags
    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    changed = False
    # Expire snoozes whose expires_at passed
    for r in io:
        if r.get("record_type") == "snooze" and r.get("account_id") == account_id and r.get("snooze_status") == "active":
            exp = _parse_dt(r.get("snooze_expires_at"))
            if exp and now_dt > exp:
                r["snooze_status"] = "expired"
                r["updated_at"] = now
                changed = True

    # Recompute materialized snoozed flags for issues/occurrences in account
    # Active issue snooze overrides (snoozed True for issue + all occurrences)
    active_issue_snoozes = {}
    active_occ_snoozes = set()
    for r in io:
        if r.get("record_type") != "snooze" or r.get("account_id") != account_id or r.get("snooze_status") != "active":
            continue
        if r.get("snooze_scope") == "issue" and isinstance(r.get("issue_id"), str):
            active_issue_snoozes[r["issue_id"]] = True
        elif r.get("snooze_scope") == "occurrence" and isinstance(r.get("occurrence_id"), str):
            active_occ_snoozes.add(r["occurrence_id"])

    # Map occurrences by issue
    occs = [r for r in io if r.get("record_type") == "occurrence" and r.get("account_id") == account_id]
    occ_ids_by_issue = {}
    for o in occs:
        occ_ids_by_issue.setdefault(o.get("issue_id"), []).append(o.get("id"))

    for r in io:
        if r.get("account_id") != account_id:
            continue
        if r.get("record_type") == "issue":
            new_val = True if active_issue_snoozes.get(r.get("id")) else False
            if r.get("snoozed") is not new_val:
                r["snoozed"] = new_val
                r["updated_at"] = now
                changed = True
        elif r.get("record_type") == "occurrence":
            if active_issue_snoozes.get(r.get("issue_id")):
                new_val = True
            else:
                new_val = True if r.get("id") in active_occ_snoozes else False
            if r.get("snoozed") is not new_val:
                r["snoozed"] = new_val
                r["updated_at"] = now
                changed = True

    if changed:
        _save("issues_occurrences.json", io)
        issues = [r for r in io if r.get("record_type") == "issue" and r.get("account_id") == account_id]
        occs = [r for r in io if r.get("record_type") == "occurrence" and r.get("account_id") == account_id]

    # Apply direct issue filters
    if severity is not None:
        issues = [i for i in issues if i.get("severity") == severity]
    if snoozed is not None:
        issues = [i for i in issues if bool(i.get("snoozed")) == snoozed]

    # Target/tag filters via occurrences join
    if target_addresses or tag_names:
        # Build candidate target_ids based on addresses and/or tags
        targets = [r for r in tt if r.get("record_type") == "target" and r.get("account_id") == account_id and r.get("target_status") != "deleted"]
        target_ids = {t.get("id") for t in targets}

        if target_addresses:
            addrset = {a.strip().lower() for a in target_addresses if isinstance(a, str)}
            addr_target_ids = {t.get("id") for t in targets if isinstance(t.get("address"), str) and t.get("address").strip().lower() in addrset}
            target_ids = target_ids.intersection(addr_target_ids)

        if tag_names:
            wanted = {n for n in tag_names if isinstance(n, str)}
            tags = [r for r in tt if r.get("record_type") == "tag" and r.get("account_id") == account_id and r.get("tag_name") in wanted]
            tag_ids = {r.get("id") for r in tags}
            if tag_ids:
                joins = [r for r in tt if r.get("record_type") == "target_tag" and r.get("account_id") == account_id and r.get("tag_id") in tag_ids]
                tag_target_ids = {j.get("target_id") for j in joins}
                target_ids = target_ids.intersection(tag_target_ids)
            else:
                target_ids = set()

        if target_ids:
            affected_issue_ids = {o.get("issue_id") for o in occs if o.get("target_id") in target_ids}
            issues = [i for i in issues if i.get("id") in affected_issue_ids]
        else:
            issues = []

    # Sorting
    sev_rank = {"critical": 4, "high": 3, "medium": 2, "low": 1}
    def _key(issue):
        v = issue.get(sort)
        if sort == "severity":
            return sev_rank.get(v, 0)
        if v is None:
            return ""
        if isinstance(v, (int, float)):
            return v
        if isinstance(v, str):
            return v
        return str(v)

    reverse = (order == "desc")
    issues_sorted = sorted(issues, key=_key, reverse=reverse)

    # Cursor pagination: cursor encodes integer offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if raw.startswith("off:"):
                offset = int(raw.split(":", 1)[1])
                if offset < 0:
                    return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            else:
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    total = len(issues_sorted)
    page = issues_sorted[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = base64.urlsafe_b64encode(f"off:{next_offset}".encode("utf-8")).decode("utf-8") if has_more else None

    return {
        "issues": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
    }

def list_scans(status=None, scan_type=None, target_addresses=None, tag_names=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0501000" if __import__("os").path.isdir("./environment_mix/0501000") else "/app/database")
    def _load(n):
        try:
