    if tag_names is not None:
        if not isinstance(tag_names, list) or any(not isinstance(x, str) for x in tag_names):
            status_code = "error"
            _log_request(account_id, user_id, None, status_code, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tag_names must be an array of strings.", field="tag_names")
        tag_names = [x.strip() for x in tag_names if isinstance(x, str) and x.strip()]

    cobj = _decode_cursor(cursor)
    if cobj == "bad":
        status_code = "error"
        _log_request(account_id, user_id, None, status_code, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
    after_key = cobj.get("after") if isinstance(cobj, dict) else None
    if after_key is not None and (not isinstance(after_key, list) or len(after_key) != 2):
        status_code = "error"
        _log_request(account_id, user_id, None, status_code, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor payload.", field="cursor")

    scans = _load("scans.json")
    if not isinstance(scans, list):
        scans = []
    headers = [r for r in scans if isinstance(r, dict) and r.get("record_type") == "scan" and r.get("account_id") == account_id]

    # Apply filters
    if status is not None:
        headers = [r for r in headers if r.get("status") == status]
    if scan_type is not None:
        headers = [r for r in headers if r.get("scan_type") == scan_type]

    # Filter by requested inputs (audit fields) if provided
    if target_addresses:
        addrset = set(target_addresses)
        def _match_addr(r):
            req = r.get("requested_target_addresses")
            if not isinstance(req, list):
                return False
            for x in req:
                nx = _norm_addr(x) if isinstance(x, str) else None
                if nx in addrset:
                    return True
            return False
        headers = [r for r in headers if _match_addr(r)]
    if tag_names:
        tagset = set(tag_names)
        def _match_tag(r):
            req = r.get("requested_tag_names")
            if not isinstance(req, list):
                return False
            return any(isinstance(x, str) and x in tagset for x in req)
        headers = [r for r in headers if _match_tag(r)]

    # Sorting with stable tie-breaker id
    def _sort_key(r):
        v = r.get(sort)
        if sort in ("started_at", "ended_at", "created_at", "updated_at"):
            dt = _parse_dt(v)
            # None sorts last in asc, first in desc by using sentinel extremes
            if dt is None:
                dt = datetime.datetime.min if order == "desc" else datetime.datetime.max
            return (dt, r.get("id") or "")
        if sort == "status":
            return (str(v) if v is not None else "", r.get("id") or "")
        return (str(v) if v is not None else "", r.get("id") or "")

    reverse = (order == "desc")
    headers.sort(key=_sort_key, reverse=reverse)

    # Cursor pagination: after=(sort_value_normalized, id)
    def _norm_sort_value(r):
        v = r.get(sort)
        if sort in ("started_at", "ended_at", "created_at", "updated_at"):
            dt = _parse_dt(v)
            if dt is None:
                return None
            return dt.isoformat()
        return v

    if after_key is not None:
        after_val, after_id = after_key[0], after_key[1]
        def _is_after(r):
            rv = _norm_sort_value(r)
            rid = r.get("id")
            if reverse:
                if rv < after_val:
                    return True
                if rv == after_val and rid < after_id:
                    return True
                return False
            else:
                if rv > after_val:
                    return True
                if rv == after_val and rid > after_id:
                    return True
                return False
        headers = [r for r in headers if _is_after(r)]

    page = headers[:limit]
    has_more = len(headers) > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor({"v": 1, "ep": endpoint, "after": [_norm_sort_value(last), last.get("id")]})

    _log_request(account_id, user_id, None, status_code, None)
    return {
        "scans": page,
        "total": len(headers),
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def list_tags(target_address=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0501000" if __import__("os").path.isdir("./environment_mix/0501000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_tags"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _norm_addr(a):
        if not isinstance(a, str):
            return None
        a = a.strip()
        if not a:
            return None
        return a.lower()

    def _log_request(account_id, user_id_ctx, status, err_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "account_id": account_id,
            "user_id": user_id_ctx,
            "credential": None,
            "status": status,
            "error_code": err_code,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if target_address is not None:
        if not isinstance(target_address, list):
            _log_request(None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "target_address must be an array of strings", field="target_address")
        norm_addrs = []
        for a in target_address:
            na = _norm_addr(a)
            if na is None:
                _log_request(None, None, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "target_address contains an invalid value", field="target_address")
            norm_addrs.append(na)
        target_address = norm_addrs

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log_request(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit", minimum=1, maximum=200)

    if sort is None:
        sort = "tag_name"
    if sort not in ("tag_name", "created_at", "updated_at"):
        _log_request(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported sort field", field="sort", allowed=["tag_name", "created_at", "updated_at"])

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log_request(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported order", field="order", allowed=["asc", "desc"])

    # Cursor: vendor observed to accept opaque strings; we treat as "start after tag id"
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        _log_request(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    au = _load("accounts_users.json")
    if not isinstance(au, list):
        au = []
    accounts = [r for r in au if isinstance(r, dict) and r.get("record_type") == "account" and r.get("account_status") == "active" and isinstance(r.get("id"), str)]
    users = [r for r in au if isinstance(r, dict) and r.get("record_type") == "user" and isinstance(r.get("id"), str) and isinstance(r.get("account_id"), str)]

    account_id_ctx = None
    user_id_ctx = None
    for a in accounts:
        aid = a["id"]
        u = next((x for x in users if x.get("account_id") == aid), None)
        if u:
            account_id_ctx = aid
            user_id_ctx = u.get("id")
            break
    if account_id_ctx is None:
        _log_request(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context available.")

    tt = _load("targets_tags.json")
    if not isinstance(tt, list):
        tt = []

    # Build mapping
    targets = [r for r in tt if isinstance(r, dict) and r.get("record_type") == "target" and r.get("account_id") == account_id_ctx]
    tags = [r for r in tt if isinstance(r, dict) and r.get("record_type") == "tag" and r.get("account_id") == account_id_ctx]
    joins = [r for r in tt if isinstance(r, dict) and r.get("record_type") == "target_tag" and r.get("account_id") == account_id_ctx]

    if target_address:
        addr_to_target_ids = {(_norm_addr(t.get("address"))): t.get("id") for t in targets if isinstance(t.get("id"), str)}
        filter_target_ids = set()
        for a in target_address:
            tid = addr_to_target_ids.get(a)
            if tid:
                filter_target_ids.add(tid)
        # If addresses provided but none match, return empty set (no error)
        if not filter_target_ids:
            _log_request(account_id_ctx, user_id_ctx, "ok", None)
            return {"tags": [], "total": 0, "limit": limit, "has_more": False, "next_cursor": None}

        tag_ids = {j.get("tag_id") for j in joins if j.get("target_id") in filter_target_ids}
        tags = [t for t in tags if t.get("id") in tag_ids]

    # Sort
    reverse = (order == "desc")

    def _sort_key(r):
        if sort == "tag_name":
            v = r.get("tag_name")
            return ("" if v is None else str(v).lower(), str(r.get("id") or ""))
        if sort == "created_at":
            dt = _parse_dt(r.get("created_at"))
            return (dt or datetime.datetime.min, str(r.get("id") or ""))
        dt = _parse_dt(r.get("updated_at"))
        return (dt or datetime.datetime.min, str(r.get("id") or ""))

    tags_sorted = sorted(tags, key=_sort_key, reverse=reverse)

    # Pagination by cursor = last seen tag id
    start_idx = 0
    if cursor:
        # Find first index strictly after the cursor id in the sorted list
        for i, r in enumerate(tags_sorted):
            if str(r.get("id")) == cursor:
                start_idx = i + 1
                break

    page = tags_sorted[start_idx:start_idx + limit]
    has_more = start_idx + limit < len(tags_sorted)
    next_cursor = page[-1].get("id") if (has_more and page and isinstance(page[-1], dict)) else None

    _log_request(account_id_ctx, user_id_ctx, "ok", None)
    return {
        "tags": page,
        "total": len(tags_sorted),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

