        return _err("VALIDATION_ERROR", "Invalid cursor payload.", field="cursor")

    io = _load("issues_occurrences.json")
    if not isinstance(io, list):
        io = []

    # Ensure issue exists within account
    issue_row = next((r for r in io if isinstance(r, dict) and r.get("record_type") == "issue" and r.get("account_id") == account_id_ctx and r.get("id") == issue_id), None)
    if issue_row is None:
        status_code = "error"
        _log_request(account_id_ctx, user_id_ctx, None, status_code, "NOT_FOUND")
        return _err("NOT_FOUND", "Issue not found.", issue_id=issue_id)

    occs = [r for r in io if isinstance(r, dict) and r.get("record_type") == "occurrence" and r.get("account_id") == account_id_ctx and r.get("issue_id") == issue_id]

    if occurrence_status is not None:
        occs = [r for r in occs if r.get("occurrence_status") == occurrence_status]
    if snoozed is not None:
        occs = [r for r in occs if bool(r.get("snoozed")) == snoozed]

    # Joins for target address/tag filters
    if target_addresses or tag_names:
        tt = _load("targets_tags.json")
        if not isinstance(tt, list):
            tt = []
        targets = [r for r in tt if isinstance(r, dict) and r.get("record_type") == "target" and r.get("account_id") == account_id_ctx]
        targets_by_id = {r.get("id"): r for r in targets if isinstance(r.get("id"), str)}
        if target_addresses:
            addrset = set(target_addresses)
            allowed_target_ids = {tid for tid, tr in targets_by_id.items() if _norm_addr(tr.get("address")) in addrset}
            occs = [r for r in occs if r.get("target_id") in allowed_target_ids]
        if tag_names:
            tagset = set(tag_names)
            tags = [r for r in tt if isinstance(r, dict) and r.get("record_type") == "tag" and r.get("account_id") == account_id_ctx and isinstance(r.get("tag_name"), str)]
            tag_ids = {r.get("id") for r in tags if r.get("tag_name") in tagset and isinstance(r.get("id"), str)}
            # which targets have these tags?
            tagged_target_ids = set()
            for r in tt:
                if not isinstance(r, dict) or r.get("record_type") != "target_tag" or r.get("account_id") != account_id_ctx:
                    continue
                if r.get("tag_id") in tag_ids and isinstance(r.get("target_id"), str):
                    tagged_target_ids.add(r.get("target_id"))
            occs = [r for r in occs if r.get("target_id") in tagged_target_ids]

    reverse = (order == "desc")
    def _sort_key(r):
        v = r.get(sort)
        if sort in ("last_seen_at", "first_seen_at", "created_at", "updated_at"):
            dt = _parse_dt(v)
            if dt is None:
                dt = datetime.datetime.min if reverse else datetime.datetime.max
            return (dt, r.get("id") or "")
        return (str(v) if v is not None else "", r.get("id") or "")

    occs.sort(key=_sort_key, reverse=reverse)

    def _norm_sort_value(r):
        v = r.get(sort)
        if sort in ("last_seen_at", "first_seen_at", "created_at", "updated_at"):
            dt = _parse_dt(v)
            return dt.isoformat() if dt else None
        return v

    if after_key is not None:
        after_val, after_id = after_key[0], after_key[1]
        def _is_after(r):
            rv = _norm_sort_value(r)
            rid = r.get("id")
            if reverse:
                if rv < after_val:
                    return True
                if rv == after_val and rid < after_id:
                    return True
                return False
            else:
                if rv > after_val:
                    return True
                if rv == after_val and rid > after_id:
                    return True
                return False
        occs = [r for r in occs if _is_after(r)]

    page = occs[:limit]
    has_more = len(occs) > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor({"v": 1, "ep": endpoint, "after": [_norm_sort_value(last), last.get("id")]})

    _log_request(account_id_ctx, user_id_ctx, None, status_code, None)
    return {
        "issue": issue_row,
        "occurrences": page,
        "total": len(occs),
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def get_scanner_output(issue_id, occurrence_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0501000" if __import__("os").path.isdir("./environment_mix/0501000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_scanner_output"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _log(status, account_id=None, user_id=None, err_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "account_id": account_id,
            "user_id": user_id,
            "credential": None,
            "status": status,
            "error_code": err_code,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_logs.json", logs)

    # Validate inputs (per tool schema)
    if not isinstance(issue_id, str) or not re.match(r"^intr_iss_[0-9A-Z]{3,}$", issue_id):
        _log("error", err_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "issue_id must match ^intr_iss_[0-9A-Z]{3,}$", field="issue_id")
    if not isinstance(occurrence_id, str) or not re.match(r"^intr_occ_[0-9A-Z]{3,}$", occurrence_id):
        _log("error", err_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "occurrence_id must match ^intr_occ_[0-9A-Z]{3,}$", field="occurrence_id")

    # Resolve an account context that can serve the request by looking for the referenced rows.
    io = _load("issues_occurrences.json")
    if not isinstance(io, list):
        io = []

    issue_row = None
    for r in io:
        if isinstance(r, dict) and r.get("record_type") == "issue" and r.get("id") == issue_id:
            issue_row = r
            break
    if not issue_row:
        _log("error", err_code="NOT_FOUND")
        return _err("NOT_FOUND", "Issue not found.", issue_id=issue_id)

    account_id_ctx = issue_row.get("account_id")
    if not isinstance(account_id_ctx, str) or not account_id_ctx:
        _log("error", err_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Unable to resolve account context for this issue.")

    occurrence_row = None
    for r in io:
        if isinstance(r, dict) and r.get("record_type") == "occurrence" and r.get("id") == occurrence_id and r.get("account_id") == account_id_ctx:
            occurrence_row = r
            break
    if not occurrence_row:
        _log("error", account_id=account_id_ctx, err_code="NOT_FOUND")
        return _err("NOT_FOUND", "Occurrence not found.", occurrence_id=occurrence_id)

    if occurrence_row.get("issue_id") != issue_id:
        _log("error", account_id=account_id_ctx, err_code="NOT_FOUND")
        return _err("NOT_FOUND", "Occurrence is not associated with the specified issue.", issue_id=issue_id, occurrence_id=occurrence_id)

    # Authorize: require the owning account to be active (ambient auth assumed; cross-account prevented by scoping above)
    au = _load("accounts_users.json")
    if not isinstance(au, list):
        au = []
    account_row = next((a for a in au if isinstance(a, dict) and a.get("record_type") == "account" and a.get("id") == account_id_ctx), None)
    if not account_row:
        _log("error", account_id=account_id_ctx, err_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account context not found.")
    if account_row.get("account_status") != "active":
        _log("error", account_id=account_id_ctx, err_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account is not active; access denied by account lifecycle rule.", account_status=account_row.get("account_status"))

    # Pick a user in that account for logging purposes (ambient)
    user_row = next((u for u in au if isinstance(u, dict) and u.get("record_type") == "user" and u.get("account_id") == account_id_ctx), None)
    user_id_ctx = user_row.get("id") if user_row else None

    _log("ok", account_id=account_id_ctx, user_id=user_id_ctx, err_code=None)
    return {
        "issue_id": issue_id,
        "occurrence_id": occurrence_id,
        "scanner_output": occurrence_row.get("scanner_output")
    }

def create_scan(target_addresses=None, tag_names=None, **_extra):
    import json, os, datetime, re, time, uuid, ipaddress

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0501000" if __import__("os").path.isdir("./environment_mix/0501000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- Ambient auth resolution: choose a working user+account combination ----
    au = _load("accounts_users.json")
    accounts = [r for r in au if r.get("record_type") == "account" and r.get("account_status") == "active"]
    users = [r for r in au if r.get("record_type") == "user" and r.get("account_id")]

    def _pick_context():
        # pick an active account that has at least one user; otherwise any user whose parent exists
        acct_by_id = {a.get("id"): a for a in accounts if a.get("id")}
        for u in users:
            a = acct_by_id.get(u.get("account_id"))
            if a:
                return (u, a)
        # fallback: any active account even without user
        if accounts:
            return (None, accounts[0])
        return (None, None)

    user_row, account_row = _pick_context()
    if not account_row:
        return _err("UNAUTHORIZED", "No authenticated account context available.")

    account_id = account_row["id"]

    # ---- Input validation ----
    if target_addresses is None:
        target_addresses = []
    if tag_names is None:
        tag_names = []

    if not isinstance(target_addresses, list) or not all(isinstance(x, str) for x in target_addresses):
        return _err("VALIDATION_ERROR", "target_addresses must be an array of strings.")
    if not isinstance(tag_names, list) or not all(isinstance(x, str) for x in tag_names):
        return _err("VALIDATION_ERROR", "tag_names must be an array of strings.")

    # Enforce schema constraints
    if len(target_addresses) > 500:
        return _err("VALIDATION_ERROR", "target_addresses exceeds maximum length of 500.")
    if len(tag_names) > 200:
        return _err("VALIDATION_ERROR", "tag_names exceeds maximum length of 200.")

    # Business rule: require at least one non-empty list
    def _nonempty_list(xs):
        return any((isinstance(x, str) and x.strip() != "") for x in xs)

    if not _nonempty_list(target_addresses) and not _nonempty_list(tag_names):
        return _err("VALIDATION_ERROR", "At least one of target_addresses or tag_names must be provided and non-empty.")

    def _normalize_addr(s):
        return s.strip().lower()

    # Basic product-like validator: domain/hostname or IPv4/IPv6 or CIDR
    _domain_re = re.compile(r"^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)(\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)*\.?$")
    def _is_valid_target_address(s):
        if not s or not isinstance(s, str):
            return False
        s = s.strip()
        if s == "":
            return False
        # IP / CIDR
        try:
            if "/" in s:
                ipaddress.ip_network(s, strict=False)
                return True
            ipaddress.ip_address(s)
            return True
        except Exception:
            pass
        # hostname/domain
        s2 = s.lower().strip()
        if len(s2) > 253:
            return False
        # disallow spaces
        if any(c.isspace() for c in s2):
            return False
        return bool(_domain_re.match(s2))

    norm_addrs = []
    for a in target_addresses:
        na = _normalize_addr(a)
        if na == "":
            continue
        if not _is_valid_target_address(na):
            return _err("VALIDATION_ERROR", f"Invalid target address: {a}")
        norm_addrs.append(na)

    norm_tags = []
    for t in tag_names:
        nt = t.strip()
        if nt == "":
            continue
        if len(nt) > 40:
            return _err("VALIDATION_ERROR", f"Tag name exceeds maximum length 40: {t}")
        norm_tags.append(nt)

    # Dedup inputs
    norm_addrs = list(dict.fromkeys(norm_addrs))
    norm_tags = list(dict.fromkeys(norm_tags))

    # ---- Resolve targets from addresses and tags (within account) ----
    tt = _load("targets_tags.json")
    targets = [r for r in tt if r.get("record_type") == "target" and r.get("account_id") == account_id]
    tags = [r for r in tt if r.get("record_type") == "tag" and r.get("account_id") == account_id]
    joins = [r for r in tt if r.get("record_type") == "target_tag" and r.get("account_id") == account_id]

    target_by_addr = {}
    target_by_id = {}
    for r in targets:
        tid = r.get("id")
        if not tid:
            continue
        target_by_id[tid] = r
        addr = r.get("address")
        if isinstance(addr, str):
            target_by_addr[addr.strip().lower()] = r

    tag_by_name = {}
    for r in tags:
        n = r.get("tag_name")
        if isinstance(n, str):
            tag_by_name[n] = r

    resolved_target_ids = set()

    # From explicit addresses: include only non-deleted targets that exist
    for addr in norm_addrs:
        tr = target_by_addr.get(addr)
        if tr and tr.get("target_status") != "deleted":
            resolved_target_ids.add(tr["id"])

    # From tags: find tag ids then join to targets (non-deleted)
    tag_ids = [tag_by_name[t]["id"] for t in norm_tags if t in tag_by_name]
    if tag_ids:
        for j in joins:
            if j.get("tag_id") in tag_ids:
                tid = j.get("target_id")
                tr = target_by_id.get(tid)
                if tr and tr.get("target_status") != "deleted":
                    resolved_target_ids.add(tid)

    # Determine eligibility: exclude non-active targets; handle license limits
    # Eligible statuses are "live" and "unscanned" (not deleted). Others count as inactive for "no_active_targets".
    eligible_statuses = {"live", "unscanned"}
    resolved_targets = [target_by_id[tid] for tid in resolved_target_ids if tid in target_by_id]
    if not resolved_targets:
        # create scan with cancelled_no_valid_targets
        scans = _load("scans.json")

        def _gen_scan_id(existing):
            chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
            existing_ids = {r.get("id") for r in existing}
            for _ in range(2000):
                suffix = "".join(chars[uuid.uuid4().int % 36] for _ in range(8))
                sid = "intr_scn_" + suffix
                if sid not in existing_ids:
                    return sid
            return "intr_scn_" + uuid.uuid4().hex[:10].upper()

        scan_id = _gen_scan_id(scans)
        created_by = user_row.get("id") if user_row else None
        scan_row = {
            "id": scan_id,
            "record_type": "scan",
            "account_id": account_id,
            "scan_id": None,
            "target_id": None,
            "status": "cancelled_no_valid_targets",
            "scan_type": "assessment_schedule",
            "requested_target_addresses": norm_addrs if norm_addrs else [],
            "requested_tag_names": norm_tags if norm_tags else [],
            "resolved_target_count": 0,
            "started_at": now,
            "ended_at": now,
            "cancel_reason": "no_valid_targets",
            "created_by_user_id": created_by,
            "created_at": now,
            "updated_at": now,
        }
        scans.append(scan_row)
        _save("scans.json", scans)
        return {
            "scan": scan_row,
            "scan_targets": [],
        }

    # Active candidates (status-based)
    status_active_ids = {t["id"] for t in resolved_targets if t.get("target_status") in eligible_statuses}

    # License enforcement (infrastructure license kind)
    lic = _load("licenses.json")
    licenses = [r for r in lic if r.get("record_type") == "license" and r.get("account_id") == account_id and r.get("license_kind") == "infrastructure" and r.get("status") == "active"]
    # If no license row exists, treat as unlimited? To remain operable, treat missing as unlimited.
    limit_total = None
    license_id = None
    if licenses:
        # pick first active infra license
        license_id = licenses[0].get("id")
        limit_total = licenses[0].get("limit_total")

    usage_rows = [r for r in lic if r.get("record_type") == "license_usage" and r.get("account_id") == account_id and r.get("usage_status") == "bound"]
    # treat expired bindings as non-bound (bound_until_at <= now)
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    bound_active = []
    for u in usage_rows:
        bu = _parse_dt(u.get("bound_until_at"))
        if bu is not None and bu <= now_dt:
            continue
        bound_active.append(u)

    bound_target_ids = {u.get("target_id") for u in bound_active if u.get("target_id")}

    eligible_ids = set(status_active_ids)

    if limit_total is not None and isinstance(limit_total, int) and limit_total >= 0:
        used = len(bound_target_ids)
        free = max(0, limit_total - used)
        # targets already bound are eligible; new ones limited by free
        already_bound = eligible_ids & bound_target_ids
        need_new = list(eligible_ids - bound_target_ids)
        allowed_new = set(need_new[:free])  # deterministic by iteration order (set -> list). Make stable:
        # make stable ordering by address then id
        need_new_sorted = sorted(list(eligible_ids - bound_target_ids), key=lambda tid: (target_by_id.get(tid, {}).get("address") or "", tid))
        allowed_new = set(need_new_sorted[:free])
        eligible_ids = already_bound | allowed_new

        # Mark excluded due to license as license_exceeded (legal transitions enforced)
        excluded = (status_active_ids - eligible_ids)
        if excluded:
            # transitions for targets: from live/unscanned/... to license_exceeded allowed
            allowed_from = {"unscanned", "live", "unresponsive", "agent_uninstalled"}
            mutated = False
            for tid in excluded:
                tr = target_by_id.get(tid)
                if not tr:
                    continue
                cur = tr.get("target_status")
                if cur in allowed_from:
                    tr["target_status"] = "license_exceeded"
                    tr["updated_at"] = now
                    mutated = True
            if mutated:
                # write back targets_tags.json with updated rows
                id_to_row = {r.get("id"): r for r in tt if r.get("id")}
                for tid, tr in target_by_id.items():
                    if tid in id_to_row:
                        id_to_row[tid] = tr
                # rebuild tt preserving original order
                new_tt = []
                for r in tt:
                    rid = r.get("id")
                    if rid and rid in id_to_row:
                        new_tt.append(id_to_row[rid])
                    else:
                        new_tt.append(r)
                _save("targets_tags.json", new_tt)

    # If after license+status filtering none remain, cancel_no_active_targets or no_valid_targets
    resolved_count = len(eligible_ids)
    scans = _load("scans.json")

    def _gen_scan_id(existing):
        chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        existing_ids = {r.get("id") for r in existing}
        for _ in range(2000):
            suffix = "".join(chars[uuid.uuid4().int % 36] for _ in range(8))
            sid = "intr_scn_" + suffix
            if sid not in existing_ids:
                return sid
        return "intr_scn_" + uuid.uuid4().hex[:10].upper()

    scan_id = _gen_scan_id(scans)
    created_by = user_row.get("id") if user_row else None

    if resolved_count == 0:
        # Distinguish: none active because status/license, vs none valid
        # Here we had resolved_targets non-empty, but eligible_ids empty implies no active targets
        status = "cancelled_no_active_targets"
        scan_row = {
            "id": scan_id,
            "record_type": "scan",
            "account_id": account_id,
            "scan_id": None,
            "target_id": None,
            "status": status,
            "scan_type": "assessment_schedule",
            "requested_target_addresses": norm_addrs if norm_addrs else [],
            "requested_tag_names": norm_tags if norm_tags else [],
            "resolved_target_count": 0,
            "started_at": now,
            "ended_at": now,
            "cancel_reason": "no_active_targets",
            "created_by_user_id": created_by,
            "created_at": now,
            "updated_at": now,
        }
        scans.append(scan_row)
        _save("scans.json", scans)
        return {"scan": scan_row, "scan_targets": []}

    # Create scan header and scan_target membership
    scan_row = {
        "id": scan_id,
        "record_type": "scan",
        "account_id": account_id,
        "scan_id": None,
        "target_id": None,
        "status": "in_progress",
        "scan_type": "assessment_schedule",
        "requested_target_addresses": norm_addrs if norm_addrs else [],
        "requested_tag_names": norm_tags if norm_tags else [],
        "resolved_target_count": resolved_count,
        "started_at": now,
        "ended_at": None,
        "cancel_reason": None,
        "created_by_user_id": created_by,
        "created_at": now,
        "updated_at": now,
    }

    # ensure no id collision (CONFLICT)
    if any(r.get("id") == scan_id for r in scans):
        return _err("CONFLICT", "Scan id collision; please retry.")

    # generate scan_target ids
    existing_scan_target_ids = {r.get("id") for r in scans if isinstance(r, dict)}
    def _gen_scan_target_id():
        chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(5000):
            suffix = "".join(chars[uuid.uuid4().int % 36] for _ in range(10))
            sid = "intr_sct_" + suffix
            if sid not in existing_scan_target_ids:
                existing_scan_target_ids.add(sid)
                return sid
        sid = "intr_sct_" + uuid.uuid4().hex[:10].upper()
        if sid in existing_scan_target_ids:
            sid = "intr_sct_" + uuid.uuid4().hex[:12].upper()
        existing_scan_target_ids.add(sid)
        return sid

    scan_target_rows = []
    for tid in sorted(list(eligible_ids), key=lambda x: (target_by_id.get(x, {}).get("address") or "", x)):
        st = {
            "id": _gen_scan_target_id(),
            "record_type": "scan_target",
            "account_id": account_id,
            "scan_id": scan_id,
            "target_id": tid,
            "status": None,
            "scan_type": None,
            "requested_target_addresses": None,
            "requested_tag_names": None,
            "resolved_target_count": None,
            "started_at": None,
            "ended_at": None,
