def cancel_scan(scan_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0501000" if __import__("os").path.isdir("./environment_mix/0501000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "cancel_scan"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _append_request_log(status, account_id=None, user_id=None, scan_id=None, error_code=None):
        # Optional observable dynamics: if a request log collection exists, append.
        for fname in ("request_logs.json", "audit_logs.json", "usage_audit.json", "api_requests.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                logs.append({
                    "id": f"intr_req_{int(time.time()*1000)}",
                    "endpoint": endpoint,
                    "account_id": account_id,
                    "user_id": user_id,
                    "scan_id": scan_id,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": _now_iso(),
                })
                _save(fname, logs)
                return

    # ---- Validate input ----
    if not isinstance(scan_id, str) or not re.match(r"^intr_scn_[0-9A-Z]{3,}$", scan_id):
        _append_request_log("error", scan_id=scan_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "scan_id must match pattern ^intr_scn_[0-9A-Z]{3,}$", scan_id=scan_id)

    # ---- Load data ----
    scans = _load("scans.json")
    if not isinstance(scans, list):
        scans = []
    au = _load("accounts_users.json")
    if not isinstance(au, list):
        au = []

    # ---- Ambient auth resolution: choose an account that can access the scan_id (preferred),
    #      otherwise any active account with a user (never fail just because no auth param) ----
    accounts = {r.get("id"): r for r in au if isinstance(r, dict) and r.get("record_type") == "account"}
    users = [r for r in au if isinstance(r, dict) and r.get("record_type") == "user"]

    scan_headers = [r for r in scans if isinstance(r, dict) and r.get("record_type") == "scan" and r.get("id") == scan_id]
    if not scan_headers:
        # If the scan doesn't exist at all, it's NOT_FOUND (as per tool contract)
        _append_request_log("error", error_code="NOT_FOUND", scan_id=scan_id)
        return _err("NOT_FOUND", "Scan not found.", scan_id=scan_id)

    # Determine which account owns this scan (data-driven, avoids choosing wrong ambient account)
    scan_row = scan_headers[0]
    scan_account_id = scan_row.get("account_id")

    # Verify the account exists; if it doesn't, treat as not accessible (data integrity)
    acct = accounts.get(scan_account_id) if isinstance(scan_account_id, str) else None
    if not isinstance(acct, dict):
        _append_request_log("error", error_code="NOT_FOUND", scan_id=scan_id)
        return _err("NOT_FOUND", "Scan not found or not accessible to your account.", scan_id=scan_id)

    # Pick a user in that account if available (for audit attribution)
    user_in_account = None
    for u in users:
        if u.get("account_id") == scan_account_id:
            user_in_account = u
            break

    # ---- Business rules: only cancellable if status in ('in_progress','analysing_results') ----
    status = scan_row.get("status")
    cancellable = status in ("in_progress", "analysing_results")
    if not cancellable:
        # Tool description says CONFLICT for non-cancellable state
        _append_request_log("error", account_id=scan_account_id, user_id=(user_in_account or {}).get("id"), scan_id=scan_id, error_code="CONFLICT")
        return _err(
            "CONFLICT",
            "Scan is not in a cancellable state. Business rule: cancel_scan allowed only when scan.status in ('in_progress','analysing_results').",
            scan_id=scan_id,
            status=status
        )

    # ---- Apply transition: in_progress/analysing_results -> cancelled ----
    now_iso = _now_iso()
    # Idempotency is not specified for cancel_scan; since status is cancellable here, we must mutate.
    scan_row["status"] = "cancelled"
    scan_row["ended_at"] = now_iso
    scan_row["cancel_reason"] = "user_request"
    scan_row["updated_at"] = now_iso

    # Persist mutation back into list
    updated = False
    for i, r in enumerate(scans):
        if isinstance(r, dict) and r.get("record_type") == "scan" and r.get("id") == scan_id:
            scans[i] = scan_row
            updated = True
            break

    if not updated:
        # Should not happen because we found it, but enforce "no success without effect"
        _append_request_log("error", account_id=scan_account_id, user_id=(user_in_account or {}).get("id"), scan_id=scan_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Scan not found.", scan_id=scan_id)

    _save("scans.json", scans)

    # Include membership rows like get_scan would? Tool says "returns the updated scan record"; return header only.
    resp = {
        "scan": scan_row
    }
    _append_request_log("ok", account_id=scan_account_id, user_id=(user_in_account or {}).get("id"), scan_id=scan_id)
    return resp

def delete_target(target_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0501000" if __import__("os").path.isdir("./environment_mix/0501000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    if not isinstance(target_id, str) or not re.match(r"^intr_tgt_[0-9A-Z]{3,}$", target_id):
        return _err("VALIDATION_ERROR", "target_id is invalid; expected format ^intr_tgt_[0-9A-Z]{3,}$.")

    # Ambient auth: resolve active account
    au = _load("accounts_users.json")
    accounts = [r for r in au if r.get("record_type") == "account" and r.get("account_status") == "active"]
    users = [r for r in au if r.get("record_type") == "user" and r.get("account_id")]
    acct_by_id = {a.get("id"): a for a in accounts if a.get("id")}
    account_row = None
    for u in users:
        a = acct_by_id.get(u.get("account_id"))
        if a:
            account_row = a
            break
    if not account_row and accounts:
        account_row = accounts[0]
    if not account_row:
        return _err("UNAUTHORIZED", "No authenticated account context available.")
    account_id = account_row["id"]

    tt = _load("targets_tags.json")
    target_idx = None
    target_row = None
    for i, r in enumerate(tt):
        if r.get("record_type") == "target" and r.get("id") == target_id and r.get("account_id") == account_id:
            target_idx = i
            target_row = r
            break
    if target_row is None:
        return _err("NOT_FOUND", "Target not found.")

    # Lifecycle: target_status -> deleted allowed from all except deleted itself
    cur = target_row.get("target_status")
    if cur == "deleted":
        # idempotent-ish: treat as NOT_FOUND? Real APIs often treat as success; but rule says no success without effect.
        return _err("NOT_FOUND", "Target is already deleted.")

    allowed_transitions = {
        "unscanned": {"live", "unresponsive", "license_exceeded", "deleted"},
        "live": {"unresponsive", "agent_uninstalled", "license_exceeded", "deleted"},
        "unresponsive": {"live", "license_exceeded", "deleted"},
        "agent_uninstalled": {"live", "license_exceeded", "deleted"},
        "license_exceeded": {"live", "deleted"},
        "deleted": set(),
    }
    if cur not in allowed_transitions or "deleted" not in allowed_transitions.get(cur, set()):
        return _err("INVALID_TRANSITION", "Target cannot be deleted from its current state.", current_status=cur)

    # Soft delete target
    target_row["target_status"] = "deleted"
    target_row["target_deleted_at"] = now
    target_row["updated_at"] = now
    tt[target_idx] = target_row

    # Delete/disable target_tag joins for this target (hard delete join rows)
    new_tt = []
    removed_joins = 0
    for r in tt:
        if r.get("record_type") == "target_tag" and r.get("account_id") == account_id and r.get("target_id") == target_id:
            removed_joins += 1
            continue
        new_tt.append(r)
    tt = new_tt
    _save("targets_tags.json", tt)

    # Expire any bound license_usage rows for this target
    lic = _load("licenses.json")
    changed_usage = 0
    for r in lic:
        if r.get("record_type") == "license_usage" and r.get("account_id") == account_id and r.get("target_id") == target_id:
            if r.get("usage_status") == "bound":
                # transition bound -> expired allowed
                r["usage_status"] = "expired"
                r["bound_until_at"] = now
                r["updated_at"] = now
                changed_usage += 1
    if changed_usage:
        _save("licenses.json", lic)

    return {
        "target": target_row,
        "deleted": True,
        "removed_target_tag_joins": removed_joins,
        "expired_license_bindings": changed_usage,
    }

def create_targets(addresses, **_extra):
    import json, os, datetime, re, ipaddress, time, uuid, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0501000" if __import__("os").path.isdir("./environment_mix/0501000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- auth (ambient): choose a valid user+account combination ----
    au = _load("accounts_users.json")
    users = [r for r in au if isinstance(r, dict) and r.get("record_type") == "user"]
    accounts = {r.get("id"): r for r in au if isinstance(r, dict) and r.get("record_type") == "account"}
    auth_user = None
    auth_account = None
    for u in users:
        acc = accounts.get(u.get("account_id"))
        if acc and acc.get("account_status") == "active":
            auth_user, auth_account = u, acc
            break
    if not auth_user or not auth_account:
        # no working account context in store
        reqlog = _load("request_log.json")
        if not isinstance(reqlog, list):
            reqlog = []
        reqlog.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "create_targets",
            "account_id": None,
            "user_id": None,
            "status": "error",
            "error_code": "UNAUTHORIZED",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_log.json", reqlog)
        return _err("UNAUTHORIZED", "No authenticated account context available.")

    account_id = auth_account.get("id")

    # ---- input validation ----
    if not isinstance(addresses, list) or len(addresses) < 1:
        return _err("VALIDATION_ERROR", "addresses must be a non-empty array of strings.", field="addresses")
    for a in addresses:
        if not isinstance(a, str):
            return _err("VALIDATION_ERROR", "Each address must be a string.", field="addresses")

    # ---- helpers ----
    def _normalize(addr):
        return addr.strip().lower()

    _re_domain = re.compile(r"^(?=.{1,253}$)([a-z0-9](?:[a-z0-9\-]{0,61}[a-z0-9])?)(\.[a-z0-9](?:[a-z0-9\-]{0,61}[a-z0-9])?)*\.?$")
    def _valid_target_address(addr_norm):
        if not addr_norm:
            return False
        if "://" in addr_norm or "/" in addr_norm and not re.search(r"/\d{1,3}$", addr_norm):
            # URLs not allowed; CIDR only allowed as ip/prefix
            pass
        # CIDR
        if "/" in addr_norm:
            try:
                ipaddress.ip_network(addr_norm, strict=False)
                return True
            except Exception:
                return False
        # IP
        try:
            ipaddress.ip_address(addr_norm)
            return True
        except Exception:
            pass
        # Domain/hostname
        if _re_domain.match(addr_norm) is None:
            return False
        # Disallow purely numeric TLD-less single label like "1234"
        if "." not in addr_norm.strip("."):
            return False
        return True

    def _new_id(prefix):
        # vendor-style uppercase base32-ish
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(10))

    # ---- load existing targets ----
    tt = _load("targets_tags.json")
    if not isinstance(tt, list):
        tt = []

    # normalize and validate all first (atomic-ish)
    normalized = []
    seen_norm = set()
    for raw in addresses:
        n = _normalize(raw)
        if not _valid_target_address(n):
            return _err("VALIDATION_ERROR", f"Invalid target address: {raw}", field="addresses")
        if n in seen_norm:
            return _err("VALIDATION_ERROR", f"Duplicate address in request: {raw}", field="addresses")
        seen_norm.add(n)
        normalized.append(n)

    # check conflicts with non-deleted existing targets
    existing = [
        r for r in tt
        if isinstance(r, dict)
        and r.get("record_type") == "target"
        and r.get("account_id") == account_id
        and r.get("target_status") != "deleted"
    ]
    existing_by_addr = {r.get("address"): r for r in existing if isinstance(r.get("address"), str)}
    for n in normalized:
        if n in existing_by_addr:
            return _err("CONFLICT", f"Target already exists for address: {n}", address=n, target_id=existing_by_addr[n].get("id"))

    # create rows
    created = []
    for n in normalized:
        tid = _new_id("intr_tgt")
        row = {
            "id": tid,
            "record_type": "target",
            "account_id": account_id,
            "target_id": None,
            "tag_id": None,
            "address": n,
            "target_status": "unscanned",
            "target_deleted_at": None,
            "tag_name": None,
            "tag_color": None,
            "last_seen_live_at": None,
            "created_at": now,
            "updated_at": now
        }
        tt.append(row)
        created.append(row)

    _save("targets_tags.json", tt)

    # request log (best-effort, no schema file given; create if missing)
    reqlog = _load("request_log.json")
    if not isinstance(reqlog, list):
        reqlog = []
    reqlog.append({
        "id": "req_" + uuid.uuid4().hex,
        "endpoint": "create_targets",
        "account_id": account_id,
        "user_id": auth_user.get("id"),
        "status": "ok",
        "latency_ms": int((time.time() - t0) * 1000),
        "created_at": now
    })
    _save("request_log.json", reqlog)

    return {
        "targets": created,
        "count": len(created)
    }

def create_target_tag(target_id, name, **_extra):
    import json, os, datetime, re, time, uuid, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0501000" if __import__("os").path.isdir("./environment_mix/0501000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # auth ambient
    au = _load("accounts_users.json")
    users = [r for r in au if isinstance(r, dict) and r.get("record_type") == "user"]
    accounts = {r.get("id"): r for r in au if isinstance(r, dict) and r.get("record_type") == "account"}
    auth_user = None
    auth_account = None
    for u in users:
        acc = accounts.get(u.get("account_id"))
        if acc and acc.get("account_status") == "active":
            auth_user, auth_account = u, acc
            break
    if not auth_user or not auth_account:
        reqlog = _load("request_log.json")
        if not isinstance(reqlog, list):
            reqlog = []
        reqlog.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "create_target_tag",
            "account_id": None,
            "user_id": None,
            "status": "error",
            "error_code": "UNAUTHORIZED",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_log.json", reqlog)
        return _err("UNAUTHORIZED", "No authenticated account context available.")

    account_id = auth_account.get("id")

    # validation
    if not isinstance(target_id, str) or re.match(r"^intr_tgt_[0-9A-Z]{3,}$", target_id) is None:
        return _err("VALIDATION_ERROR", "target_id is malformed.", field="target_id")
    if not isinstance(name, str):
        return _err("VALIDATION_ERROR", "name must be a string.", field="name")
    tag_name = name.strip()
    if len(tag_name) == 0:
        return _err("VALIDATION_ERROR", "name must not be empty.", field="name")
    if len(tag_name) > 40:
        return _err("VALIDATION_ERROR", "name exceeds maximum length of 40.", field="name")

    tt = _load("targets_tags.json")
    if not isinstance(tt, list):
        tt = []

    # find target in account and not deleted
    target = None
    for r in tt:
        if isinstance(r, dict) and r.get("record_type") == "target" and r.get("id") == target_id and r.get("account_id") == account_id:
            target = r
            break
    if not target or target.get("target_status") == "deleted":
        return _err("NOT_FOUND", "Target not found.")

    # upsert tag by (account_id, tag_name)
    tag = None
    for r in tt:
        if isinstance(r, dict) and r.get("record_type") == "tag" and r.get("account_id") == account_id and r.get("tag_name") == tag_name:
            tag = r
            break

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(10))

    if not tag:
        tag = {
            "id": _new_id("intr_tag"),
            "record_type": "tag",
            "account_id": account_id,
            "target_id": None,
            "tag_id": None,
            "address": None,
            "target_status": None,
            "target_deleted_at": None,
            "tag_name": tag_name,
            "tag_color": None,
            "last_seen_live_at": None,
            "created_at": now,
            "updated_at": now
        }
        tt.append(tag)
    else:
        # touch
        tag["updated_at"] = now

    # check join exists (idempotent per business rules)
    join = None
    for r in tt:
        if isinstance(r, dict) and r.get("record_type") == "target_tag" and r.get("account_id") == account_id and r.get("target_id") == target_id and r.get("tag_id") == tag.get("id"):
            join = r
            break

    if not join:
        join = {
            "id": _new_id("intr_ttg"),
            "record_type": "target_tag",
            "account_id": account_id,
            "target_id": target_id,
            "tag_id": tag.get("id"),
            "address": None,
            "target_status": None,
            "target_deleted_at": None,
            "tag_name": None,
            "tag_color": None,
            "last_seen_live_at": None,
            "created_at": now,
            "updated_at": now
        }
        tt.append(join)

    # update target timestamp
    target["updated_at"] = now

    _save("targets_tags.json", tt)

