def list_licenses(license_kind=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0501000" if __import__("os").path.isdir("./environment_mix/0501000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # auth ambient
    au = _load("accounts_users.json")
    users = [r for r in au if isinstance(r, dict) and r.get("record_type") == "user"]
    accounts = {r.get("id"): r for r in au if isinstance(r, dict) and r.get("record_type") == "account"}
    auth_user = None
    auth_account = None
    for u in users:
        acc = accounts.get(u.get("account_id"))
        if acc and acc.get("account_status") == "active":
            auth_user, auth_account = u, acc
            break
    if not auth_user or not auth_account:
        reqlog = _load("request_log.json")
        if not isinstance(reqlog, list):
            reqlog = []
        reqlog.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "list_licenses",
            "account_id": None,
            "user_id": None,
            "status": "error",
            "error_code": "UNAUTHORIZED",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_log.json", reqlog)
        return _err("UNAUTHORIZED", "No authenticated account context available.")

    account_id = auth_account.get("id")

    # validation
    if license_kind is not None and license_kind not in ("infrastructure", "application"):
        return _err("VALIDATION_ERROR", "Invalid license_kind.", field="license_kind")
    if status is not None and status not in ("active", "expired", "cancelled"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if limit is None:
        limit_i = 100
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")
        limit_i = limit
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    lic = _load("licenses.json")
    if not isinstance(lic, list):
        lic = []

    # Parse cursor as offset (opaque-ish)
    offset = 0
    if cursor:
        try:
            if cursor.startswith("off_"):
                offset = int(cursor.split("_", 1)[1])
            else:
                offset = int(cursor)
            if offset < 0:
                offset = 0
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # Compute active bound usage rows at now, and also expire those past bound_until_at (background-like upkeep)
    changed = False
    usage_rows = [r for r in lic if isinstance(r, dict) and r.get("record_type") == "license_usage" and r.get("account_id") == account_id]
    for r in usage_rows:
        if r.get("usage_status") == "bound" and r.get("bound_until_at"):
            try:
                bu = datetime.datetime.fromisoformat(r["bound_until_at"].replace("Z", "+00:00"))
                if bu <= now_dt.replace(tzinfo=datetime.timezone.utc):
                    r["usage_status"] = "expired"
                    r["updated_at"] = now
                    changed = True
            except Exception:
                # leave as-is if malformed timestamp
                pass
    if changed:
        _save("licenses.json", lic)

    # Build entitlements list filtered
    entitlements = [
        r for r in lic
        if isinstance(r, dict)
        and r.get("record_type") == "license"
        and r.get("account_id") == account_id
    ]
    if license_kind is not None:
        entitlements = [r for r in entitlements if r.get("license_kind") == license_kind]
    if status is not None:
        entitlements = [r for r in entitlements if r.get("status") == status]

    # sort stable by kind then id
    entitlements.sort(key=lambda r: ((r.get("license_kind") or ""), (r.get("id") or "")))

    total = len(entitlements)
    page = entitlements[offset: offset + limit_i]
    has_more = offset + limit_i < total
    next_cursor = f"off_{offset + limit_i}" if has_more else None

    # For each license compute used_current and attach bindings
    def _is_bound_active(urow):
        if urow.get("usage_status") != "bound":
            return False
        bu = urow.get("bound_until_at")
        if not bu:
            return True
        try:
            bu_dt = datetime.datetime.fromisoformat(bu.replace("Z", "+00:00"))
            return bu_dt > now_dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return False

    out = []
    for lrow in page:
        lid = lrow.get("id")
        kind = lrow.get("license_kind")
        bound = [u for u in usage_rows if u.get("license_id") == lid and _is_bound_active(u)]
        used_current = len(bound)
        # materialize into response (do not overwrite stored used_current unless you must)
        o = dict(lrow)
        o["used_current"] = used_current
        o["bindings"] = [{
            "id": u.get("id"),
            "target_id": u.get("target_id"),
            "bound_from_at": u.get("bound_from_at"),
            "bound_until_at": u.get("bound_until_at"),
            "usage_status": u.get("usage_status")
        } for u in sorted(bound, key=lambda x: (x.get("bound_from_at") or "", x.get("id") or ""))]
        out.append(o)

    reqlog = _load("request_log.json")
    if not isinstance(reqlog, list):
        reqlog = []
    reqlog.append({
        "id": "req_" + uuid.uuid4().hex,
        "endpoint": "list_licenses",
        "account_id": account_id,
        "user_id": auth_user.get("id"),
        "status": "ok",
        "latency_ms": int((time.time() - t0) * 1000),
        "created_at": now
    })
    _save("request_log.json", reqlog)

    return {
        "licenses": out,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def snooze_issue(issue_id, reason, details=None, duration=None, duration_type=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0501000" if __import__("os").path.isdir("./environment_mix/0501000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "snooze_issue"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log_request(account_id, user_id_ctx, status, err_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "account_id": account_id,
            "user_id": user_id_ctx,
            "credential": None,
            "status": status,
            "error_code": err_code,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(issue_id, str) or not issue_id.strip():
        _log_request(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "issue_id must be a non-empty string", field="issue_id")
    if reason not in ("ACCEPT_RISK", "FALSE_POSITIVE", "MITIGATING_CONTROLS"):
        _log_request(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid reason.", field="reason", allowed=["ACCEPT_RISK", "FALSE_POSITIVE", "MITIGATING_CONTROLS"])
    if duration is not None and (not isinstance(duration, int) or duration < 1):
        _log_request(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "duration must be an integer >= 1 when provided", field="duration", minimum=1)
    if details is not None and not isinstance(details, str):
        _log_request(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "details must be a string when provided", field="details")
    if duration_type is not None and not isinstance(duration_type, str):
        _log_request(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "duration_type must be a string when provided", field="duration_type")

    # Ambient auth context
    au = _load("accounts_users.json")
    if not isinstance(au, list):
        au = []
    accounts = [r for r in au if isinstance(r, dict) and r.get("record_type") == "account" and r.get("account_status") == "active" and isinstance(r.get("id"), str)]
    users = [r for r in au if isinstance(r, dict) and r.get("record_type") == "user" and isinstance(r.get("id"), str) and isinstance(r.get("account_id"), str)]

    account_id_ctx = None
    user_id_ctx = None
    for a in accounts:
        aid = a["id"]
        u = next((x for x in users if x.get("account_id") == aid), None)
        if u:
            account_id_ctx = aid
            user_id_ctx = u.get("id")
            break
    if account_id_ctx is None:
        _log_request(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context available.")

    rows = _load("issues_occurrences.json")
    if not isinstance(rows, list):
        rows = []

    now_dt = _now_dt()
    now_iso = _now_iso()

    # Background expiry sweep for this account/issue (keeps materialized flags correct)
    changed = False
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "snooze" or r.get("account_id") != account_id_ctx:
            continue
        if r.get("snooze_status") != "active":
            continue
        exp = _parse_dt(r.get("snooze_expires_at"))
        if exp is not None and now_dt > exp:
            r["snooze_status"] = "expired"
            r["updated_at"] = now_iso
            changed = True

    issue = next((r for r in rows if isinstance(r, dict) and r.get("record_type") == "issue" and r.get("account_id") == account_id_ctx and r.get("id") == issue_id), None)
    if not issue:
        exists_elsewhere = any(isinstance(r, dict) and r.get("record_type") == "issue" and r.get("id") == issue_id for r in rows)
        if exists_elsewhere:
            _log_request(account_id_ctx, user_id_ctx, "error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Not permitted to access this issue.")
        _log_request(account_id_ctx, user_id_ctx, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Issue not found", issue_id=issue_id)

    # Replace existing active issue-scope snooze (idempotent replace semantics)
    existing_active = next((r for r in rows if isinstance(r, dict) and r.get("record_type") == "snooze" and r.get("account_id") == account_id_ctx and r.get("issue_id") == issue_id and r.get("snooze_scope") == "issue" and r.get("snooze_status") == "active"), None)
    if existing_active:
        existing_active["snooze_reason"] = reason
        existing_active["snooze_details"] = details
        existing_active["snooze_duration_seconds"] = duration
        existing_active["snooze_duration_type"] = duration_type
        if duration is not None:
            existing_active["snooze_expires_at"] = (now_dt + datetime.timedelta(seconds=duration)).isoformat().replace("+00:00", "Z")
        else:
            existing_active["snooze_expires_at"] = None
        existing_active["updated_at"] = now_iso
        existing_active["created_by_user_id"] = user_id_ctx
        snooze_row = existing_active
        changed = True
    else:
        # Create new snooze row
        # generate id in a stable-ish way
        new_id = f"intr_snz_{int(time.time()*1000)}_{os.getpid()}"
        snooze_row = {
            "id": new_id,
            "record_type": "snooze",
            "account_id": account_id_ctx,
            "issue_id": issue_id,
            "occurrence_id": None,
            "snooze_scope": "issue",
            "snooze_reason": reason,
            "snooze_details": details,
            "snooze_duration_seconds": duration,
            "snooze_duration_type": duration_type,
            "snooze_expires_at": (now_dt + datetime.timedelta(seconds=duration)).isoformat().replace("+00:00", "Z") if duration is not None else None,
            "snooze_status": "active",
            "created_by_user_id": user_id_ctx,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        rows.append(snooze_row)
        changed = True

    # Materialize snoozed flags: issue and all its occurrences true while issue-scope snooze active
    issue["snoozed"] = True
    issue["updated_at"] = now_iso
    for r in rows:
        if isinstance(r, dict) and r.get("record_type") == "occurrence" and r.get("account_id") == account_id_ctx and r.get("issue_id") == issue_id:
            r["snoozed"] = True
            r["updated_at"] = now_iso
    changed = True

    if changed:
        _save("issues_occurrences.json", rows)

    _log_request(account_id_ctx, user_id_ctx, "ok", None)
    return {"issue": issue, "snooze": snooze_row}

