    if reason not in ("ACCEPT_RISK", "FALSE_POSITIVE", "MITIGATING_CONTROLS"):
        _log("error", err_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reason must be one of ACCEPT_RISK, FALSE_POSITIVE, MITIGATING_CONTROLS", field="reason")
    if duration is not None:
        if not isinstance(duration, int):
            _log("error", err_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "duration must be an integer number of seconds.", field="duration")
        if duration < 1:
            _log("error", err_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "duration must be >= 1 when provided.", field="duration")

    io = _load("issues_occurrences.json")
    if not isinstance(io, list):
        io = []

    issue_row = next((r for r in io if isinstance(r, dict) and r.get("record_type") == "issue" and r.get("id") == issue_id), None)
    if not issue_row:
        _log("error", err_code="NOT_FOUND")
        return _err("NOT_FOUND", "Issue not found.", issue_id=issue_id)

    account_id_ctx = issue_row.get("account_id")
    if not isinstance(account_id_ctx, str) or not account_id_ctx:
        _log("error", err_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Unable to resolve account context for this issue.")

    occurrence_row = next((r for r in io if isinstance(r, dict) and r.get("record_type") == "occurrence" and r.get("id") == occurrence_id and r.get("account_id") == account_id_ctx), None)
    if not occurrence_row:
        _log("error", account_id=account_id_ctx, err_code="NOT_FOUND")
        return _err("NOT_FOUND", "Occurrence not found.", occurrence_id=occurrence_id)

    if occurrence_row.get("issue_id") != issue_id:
        _log("error", account_id=account_id_ctx, err_code="NOT_FOUND")
        return _err("NOT_FOUND", "Occurrence is not associated with the specified issue.", issue_id=issue_id, occurrence_id=occurrence_id)

    # Authorize by account lifecycle (ambient auth assumed)
    au = _load("accounts_users.json")
    if not isinstance(au, list):
        au = []
    account_row = next((a for a in au if isinstance(a, dict) and a.get("record_type") == "account" and a.get("id") == account_id_ctx), None)
    if not account_row:
        _log("error", account_id=account_id_ctx, err_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account context not found.")
    if account_row.get("account_status") != "active":
        _log("error", account_id=account_id_ctx, err_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account is not active; access denied by account lifecycle rule.", account_status=account_row.get("account_status"))

    user_row = next((u for u in au if isinstance(u, dict) and u.get("record_type") == "user" and u.get("account_id") == account_id_ctx), None)
    user_id_ctx = user_row.get("id") if user_row else None

    now = _now_dt()
    now_iso = _now_iso()

    # Expire any existing active snooze for this occurrence (idempotent replace)
    changed = False
    for r in io:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "snooze":
            continue
        if r.get("account_id") != account_id_ctx:
            continue
        if r.get("snooze_scope") != "occurrence":
            continue
        if r.get("issue_id") != issue_id:
            continue
        if r.get("occurrence_id") != occurrence_id:
            continue
        if r.get("snooze_status") == "active":
            r["snooze_status"] = "revoked"
            r["updated_at"] = now_iso
            changed = True

    # Create a new active snooze row
    # Generate id in a stable local convention
    existing_ids = [r.get("id") for r in io if isinstance(r, dict) and isinstance(r.get("id"), str)]
    snooze_id = None
    for _ in range(10):
        candidate = f"intr_snz_{int(time.time()*1000)}_{os.getpid()}"
        if candidate not in existing_ids:
            snooze_id = candidate
            break
    if snooze_id is None:
        snooze_id = f"intr_snz_{int(time.time())}_{os.getpid()}"

    expires_at = None
    if duration is not None:
        expires_at = now + datetime.timedelta(seconds=duration)

    snooze_row = {
        "id": snooze_id,
        "record_type": "snooze",
        "account_id": account_id_ctx,
        "issue_id": issue_id,
        "occurrence_id": occurrence_id,
        "target_id": None,
        "scan_id": None,
        "severity": None,
        "title": None,
        "description": None,
        "first_seen_at": None,
        "last_seen_at": None,
        "occurrence_status": None,
        "evidence": None,
        "scanner_output": None,
        "snoozed": None,
        "snooze_scope": "occurrence",
        "snooze_reason": reason,
        "snooze_details": details,
        "snooze_duration_seconds": duration,
        "snooze_duration_type": duration_type,
        "snooze_expires_at": _fmt_dt(expires_at),
        "snooze_status": "active",
        "created_by_user_id": user_id_ctx,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    io.append(snooze_row)
    changed = True

    # Materialize snoozed=true for the occurrence while the snooze is active.
    # (Issue-scope snooze overrides, but setting occurrence true is correct while active either way.)
    occ_changed = False
    for r in io:
        if isinstance(r, dict) and r.get("record_type") == "occurrence" and r.get("id") == occurrence_id and r.get("account_id") == account_id_ctx:
            if r.get("snoozed") is not True:
                r["snoozed"] = True
                r["updated_at"] = now_iso
                occ_changed = True
            occurrence_row = r
            break

    if changed or occ_changed:
        _save("issues_occurrences.json", io)
    else:
        _log("error", account_id=account_id_ctx, user_id=user_id_ctx, err_code="NOT_FOUND")
        return _err("NOT_FOUND", "No changes applied; occurrence not found.", occurrence_id=occurrence_id)

    _log("ok", account_id=account_id_ctx, user_id=user_id_ctx, err_code=None)
    # Return the updated occurrence plus snooze metadata (minimal, per description)
    return {
        "occurrence": occurrence_row,
        "snooze": snooze_row
    }
